#!/bin/bash
# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: chezmoi run-once script that hooks .os/rc (the `os` alias, start-in-repo) into ~/.bashrc.
# Appends the line rather than managing ~/.bashrc, since Omarchy owns that file.
# ---------------------------------------------------------------------------
set -euo pipefail

line='source $HOME/repos/delulu-smash/.os/rc'
grep -qxF "$line" "$HOME/.bashrc" || printf '\n%s\n' "$line" >>"$HOME/.bashrc"
